// Restored from the original Kokoro worker. Serialize inference and preserve the remote model host while loading.
let tts=null,loading=null,modelHost='',queue=Promise.resolve();
async function init(host){if(host)modelHost=host;if(tts)return tts;if(!loading)loading=(async()=>{const here=new URL('./',self.location.href).href;self.KOKORO_HOST=modelHost||here;const m=await import('./kokoro.web.js');m.env.wasmPaths=here;tts=await m.KokoroTTS.from_pretrained('onnx-community/Kokoro-82M-v1.0-ONNX',{dtype:'q8',device:'wasm',progress_callback:p=>{if(p.status==='progress'&&p.total)postMessage({t:'progress',file:p.file,loaded:p.loaded,total:p.total});}});postMessage({t:'ready'});return tts;})().catch(e=>{loading=null;throw e;});return loading;}
self.onmessage=e=>{const d=e.data;if(d.t==='init'){init(d.host).catch(e=>postMessage({t:'error',msg:String(e.message||e)}));return;}if(d.t==='say'){queue=queue.then(async()=>{try{const t=await init(),a=await t.generate(d.text,{voice:d.voice||'af_heart',speed:d.speed||.92}),pcm=new Float32Array(a.audio);postMessage({t:'audio',id:d.id,pcm,sr:a.sampling_rate},[pcm.buffer]);}catch(e){postMessage({t:'error',id:d.id,msg:String(e.message||e)});}});}};
